// stlport
// A run given as a pair of ends passed on as a start and a length, built
// without optimisation. The callee is pinned by address; nothing here names it.

#define _STLP_USE_OWN_NAMESPACE 1
#include "Common/STLTypedefs.h"
#include <algorithm>
#include <string>

extern "C" void _ReadWriteBarrier(void);
#pragma intrinsic(_ReadWriteBarrier)

struct BfmeRangePE
{
	char *m_bfmeAt;				// 0x0
	char *m_bfmeEnd;			// 0x4
};

class BfmeThingPE
{
public:
	void bfmeGoPE(const BfmeRangePE *span, void *what);

	unsigned int bfmeDoPE(const char *at, unsigned int what, unsigned int many);

	const char *m_bfmeAt;
	const char *m_bfmeEnd;
};

#pragma optimize("", off)
void BfmeThingPE::bfmeGoPE(const BfmeRangePE *span, void *what)
{
	bfmeDoPE(span->m_bfmeAt, (unsigned int)what,
		span->m_bfmeEnd - span->m_bfmeAt);
}

#pragma optimize("gty", on)
unsigned int BfmeThingPE::bfmeDoPE(const char *at, unsigned int what, unsigned int many)
{
	const unsigned int npos = (unsigned int)-1;
	const char *first = m_bfmeAt;
	const char *last = m_bfmeEnd;

	if (what + many > (unsigned int)(last - first))
	{
		_ReadWriteBarrier();
		return npos;
	}

	const char *result = _STL::search(
			first + what, last, at, at + many,
			_STL::_Eq_traits<_STL::char_traits<char> >());
	if (result == last)
	{
		// Retail keeps a second copy of the pop/return tail here. The barrier
		// is an optimizer-only CFG anchor and emits no instruction.
		_ReadWriteBarrier();
		return npos;
	}
	return result - first;
}

#pragma optimize("", off)
